06_EncodeCall.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract C { function f(int) public {} function f2(int, int) public {} function wrongType() public view returns (bytes memory) { return abi.encodeCall(this.f, ("test")); } function tooMany() public view returns (bytes memory) { return abi.encodeCall(this.f, (1, 2)); } function tooFew() public view returns (bytes memory) { return abi.encodeCall(this.f, ()); } function missingTuple() public view returns (bytes memory) { return abi.encodeCall(this.f); } function arrayInsteadOfTuple() public view returns (bytes memory) { return abi.encodeCall(this.f2, [1, 2]); } }

07_EncodeCallKinds.sol.content:
