pragma solidity 0.8.36;
contract C { function internalFunction(uint) internal pure {} function firstNotFunction() public pure returns (bytes memory) { return abi.encodeCall(1, (2)); } function internalKind() public pure returns (bytes memory) { return abi.encodeCall(internalFunction, (2)); } }
